// Üretilen dosya: tool/ozgun/uret.py. Biyoloji · DNA, gen ifadesi ve biyoteknoloji (kolay).
const ozBiology10Kolay = <(String, String, List<String>, String)>[
  ('1869\'da irin dolu sargı bezlerindeki akyuvarların çekirdeklerinden fosforca zengin, asidik bir madde ayırarak buna "nüklein" adını veren İsviçreli bilim insanı kimdir?', 'Friedrich Miescher', ['Albrecht Kossel', 'Phoebus Aaron Levene', 'Thomas Hunt Morgan'], 'Miescher 1869\'da Tübingen\'de akyuvar çekirdeklerinden nükleini ayırmıştır; bu madde bugün nükleik asit olarak bilinir.'),
  ('DNA\'nın çift sarmal yapısını öneren Watson ve Crick makalesi hangi yıl ve hangi dergide yayımlanmıştır?', '1953, Nature', ['1944, Science', '1962, Cell', '1958, The Lancet'], 'Watson ve Crick\'in tek sayfalık modeli 25 Nisan 1953\'te Nature dergisinde yayımlanmıştır.'),
  ('Watson ve Crick ile birlikte 1962 Nobel Fizyoloji veya Tıp Ödülü\'nü paylaşan, DNA\'nın X ışını kırınım çalışmalarını yürüten bilim insanı kimdir?', 'Maurice Wilkins', ['Rosalind Franklin', 'Erwin Chargaff', 'Max Delbrück'], 'Ödül Watson, Crick ve Wilkins\'e verildi. Franklin 1958\'de öldüğü için ödüle aday olamadı; Nobel ölümünden sonra verilmez.'),
  ('Adenin ve guanin "pürin", sitozin, timin ve urasil ise "pirimidin" olarak sınıflandırılır. Bu ayrımın yapısal temeli nedir?', 'Pürinlerde çift halka, pirimidinlerde tek halka bulunması', ['Pürinlerde fosfor, pirimidinlerde kükürt bulunması', 'Pürinlerin yalnızca RNA\'da, pirimidinlerin DNA\'da yer alması', 'Pürinlerin şekere, pirimidinlerin fosfata bağlanması'], 'Pürinler birbirine kaynaşmış iki halkadan, pirimidinler ise tek altı üyeli halkadan oluşan azotlu bazlardır.'),
  ('Bir azotlu bazın yalnızca beş karbonlu şekere bağlı olduğu, fosfat grubu taşımayan birime ne ad verilir?', 'Nükleozit', ['Nükleotit', 'Nükleozom', 'Nükleoprotein'], 'Baz + şeker nükleozit, buna bir ya da daha çok fosfat eklenince nükleotit oluşur. Örneğin adenozin bir nükleozit, AMP bir nükleotittir.'),
  ('Bir nükleotitte azotlu baz şekerin hangi karbon atomuna bağlıdır?', '1\' karbonuna', ['2\' karbonuna', '3\' karbonuna', 'Fosfata bağlı 5\' karbonuna'], 'Baz, şekerin 1\' karbonuna N-glikozit bağıyla bağlanır; fosfat 5\' karbonunda, bir sonraki nükleotiti bağlayan hidroksil ise 3\' karbonundadır.'),
  ('Bir DNA zincirinin "5\' ucu" ile "3\' ucu" arasındaki kimyasal fark aşağıdakilerden hangisidir?', '5\' ucunda serbest fosfat, 3\' ucunda serbest hidroksil grubu bulunur.', ['5\' ucunda pürin, 3\' ucunda pirimidin bazı bulunur.', '5\' ucunda riboz şekeri, 3\' ucunda ise deoksiriboz şekeri bulunur ve zincir burada sonlanır.', '5\' ucunda hidrojen bağı, 3\' ucunda peptit bağı bulunur.'], 'Zincirin bir ucundaki son nükleotitin 5\' karbonundaki fosfat, diğer ucundaki son nükleotitin 3\' karbonundaki OH grubu serbesttir.'),
  ('Deoksiriboz şekerini ribozdan ayıran özellik nedir?', '2\' karbonunda bir oksijen atomu eksik olması', ['Altı karbon atomu içermesi', 'Halka yapısının açık zincir hâlinde ve altı karbonlu olması', '5\' karbonunda fosfat bulunmaması'], 'Deoksi "oksijeni eksik" anlamına gelir; deoksiribozun 2\' karbonunda OH yerine yalnızca H bulunur.'),
  ('Pürinler ve pirimidinler için aşağıdaki eşleştirmelerden hangisi doğrudur?', 'Guanin – pürin, Sitozin – pirimidin', ['Adenin – pirimidin, Timin – pürin', 'Urasil – pürin, Guanin – pirimidin', 'Sitozin – pürin, Adenin ile Timin – pirimidin'], 'Adenin ve guanin pürindir; sitozin, timin ve urasil pirimidindir.'),
  ('Timin ile urasil arasındaki tek kimyasal fark aşağıdakilerden hangisidir?', 'Timinde fazladan bir metil grubu bulunması', ['Urasilin çift halkalı bir pürin olması', 'Timinin şekere 3\' karbonundan bağlanması', 'Urasilin yapısında hiç azot bulunmaması'], 'Timin 5-metilurasildir; urasilin halkasındaki bir hidrojen yerine metil grubu taşır.'),
  ('Nükleik asitlerin "asit" olarak adlandırılmasının nedeni aşağıdakilerden hangisidir?', 'Fosfat gruplarının proton verebilmesi', ['Azotlu bazların proton bağlaması', 'Şekerlerin karboksil grubu taşıması', 'Hücrede yalnızca asidik ortamda bulunmaları'], 'Omurgadaki fosfat grupları fizyolojik pH\'ta proton kaybederek negatif yüklenir; molekülün asidik karakteri buradan gelir.'),
  ('Tek zincirli bir DNA parçasının dizisi 5\'-AGTC-3\' şeklindedir. Bu parçada kaç fosfodiester bağı vardır?', '3', ['4', '2', '12'], 'Dört nükleotit art arda üç fosfodiester bağıyla bağlanır; doğrusal tek zincirde bağ sayısı nükleotit sayısının bir eksiğidir.'),
  ('Hücrelerde en yaygın görülen B biçimli DNA sarmalının bir tam dönüşünde yaklaşık kaç baz çifti bulunur?', '10', ['4', '100', '36'], 'B-DNA\'da her tam turda yaklaşık 10 (10,5) baz çifti yer alır ve bir tur yaklaşık 3,4 nm uzunluğundadır.'),
  ('Çift sarmal DNA\'nın çapı yaklaşık ne kadardır?', '2 nm', ['20 nm', '0,2 nm', '200 nm'], 'B-DNA\'nın çapı yaklaşık 2 nm\'dir; bu sabit çap bir pürin ile bir pirimidinin eşleşmesiyle korunur.'),
  ('Doğadaki DNA\'ların büyük çoğunluğunda sarmalın dönüş yönü için hangisi doğrudur?', 'Sağ el yönündedir.', ['Sol el yönündedir.', 'Yönü rastgele değişir.', 'Sarmal yoktur, düz merdiven biçimindedir.'], 'B-DNA ve A-DNA sağ el sarmalıdır; sol el yönünde dönen Z-DNA ise belirli dizilerde nadiren oluşan bir biçimdir.'),
  ('Çift zincirli DNA ısıtıldığında iki zincirin birbirinden ayrılmasına ne ad verilir?', 'Denatürasyon', ['Hibridizasyon', 'Translokasyon', 'Polimerizasyon'], 'Isı hidrojen bağlarını koparır ve zincirler ayrılır; buna denatürasyon (erime) denir. Kovalent fosfodiester bağları bozulmaz.'),
  ('Isıyla ayrılmış DNA zincirleri yavaşça soğutulduğunda tamamlayıcı zincirlerin yeniden eşleşerek çift sarmal oluşturmasına ne ad verilir?', 'Renatürasyon', ['Transkripsiyon', 'Rekombinasyon', 'Translasyon'], 'Yavaş soğutmada tamamlayıcı zincirler yeniden eşleşir; bu olaya renatürasyon ya da yeniden birleşme (annealing) denir.'),
  ('Farklı kaynaklardan gelen iki tek zincirli nükleik asidin baz eşleşmesi yaparak çift zincirli bir melez oluşturmasına dayanan teknik genel olarak ne ad alır?', 'Hibridizasyon', ['Jel elektroforezi', 'Hücre füzyonu', 'Kromatografi'], 'Hibridizasyonda işaretli bir tek zincir (prob) yalnızca tamamlayıcısıyla eşleşir; dizi benzerliği bu yolla saptanır.'),
  ('Kromatinin elektron mikroskobunda "ipe dizilmiş boncuklar" gibi görünmesinde "boncuk" ve "ip" neye karşılık gelir?', 'Boncuk nükleozom, ip nükleozomlar arasındaki bağlayıcı DNA', ['Boncuk ribozom, ip mRNA', 'Boncuk sentromer, ip kromatit', 'Boncuk gen, ip ise genler arasındaki intron dizileri'], 'Gevşetilmiş kromatinde nükleozomlar boncuk gibi, aralarındaki bağlayıcı DNA ise ip gibi görünür (yaklaşık 10 nm lif).'),
  ('Histon proteinlerinin DNA\'ya sıkıca bağlanabilmesi, yapılarında hangi amino asitlerin bol bulunmasıyla açıklanır?', 'Lizin ve arjinin gibi pozitif yüklü amino asitlerin', ['Glutamik asit ve aspartik asit gibi negatif yüklü amino asitlerin', 'Sistein gibi kükürt içeren amino asitlerin', 'Triptofan gibi halkalı amino asitlerin'], 'Lizin ve arjininin pozitif yan zincirleri DNA omurgasındaki negatif fosfatlarla elektrostatik etkileşim kurar.'),
  ('İnsanda bir diploit hücredeki DNA yaklaşık 2 metre uzunluğundadır ve yaklaşık 6 µm çaplı bir çekirdeğe sığar. Bu durumu mümkün kılan temel süreç nedir?', 'DNA\'nın proteinlerle birlikte kademeli olarak paketlenmesi', ['DNA\'nın çekirdekte parçalara ayrılıp yıkılması', 'DNA\'nın sitoplazmada saklanıp gerektiğinde çekirdeğe girmesi', 'Bazların aralarındaki uzaklığın sıfıra inmesi'], 'DNA nükleozomlara, 30 nm life, ilmeklere ve sonunda kromozomlara doğru kademeli olarak sarılıp katlanır.'),
  ('Canlıların genom büyüklüğünün karmaşıklıklarıyla doğru orantılı olmaması (örneğin bazı amiplerin ve soğanın genomunun insanınkinden çok büyük olması) hangi adla bilinir?', 'C-değeri paradoksu', ['Hayflick sınırı', 'Chargaff kuralı', 'Merkezî dogma'], 'Genom büyüklüğü (C-değeri) büyük ölçüde kodlamayan tekrarlı DNA miktarına bağlıdır; bu nedenle organizmanın karmaşıklığını yansıtmaz.'),
  ('İnsan genomundaki tekrarlı DNA dizileriyle ilgili hangisi doğrudur?', 'Genomun yaklaşık yarısı tekrarlı dizilerden oluşur.', ['Genomun yalnızca %1\'inden azı tekrarlı dizidir.', 'Tekrarlı diziler yalnızca mitokondride bulunur.', 'Tekrarlı dizilerin tamamı protein kodlayan genlerdir.'], 'Transpozon kökenli diziler tek başına insan genomunun yaklaşık %45\'ini oluşturur; uydu DNA\'lar gibi diğer tekrarlarla birlikte bu oran yarıyı aşar.'),
  ('Bitki hücrelerinde kloroplast DNA\'sı için aşağıdakilerden hangisi doğrudur?', 'Halkasaldır; bazı fotosentez proteinlerini kodlar.', ['Çekirdek DNA\'sından daha uzundur ve histonlara sarılıdır.', 'Yalnız erkek gametlerle kalıtılır.', 'Hiçbir gen taşımayan bir yedek DNA\'dır.'], 'Kloroplast genomu genellikle 120–160 kb\'lık halkasal bir moleküldür; Rubisco\'nun büyük alt birimi gibi bazı proteinleri kodlar.'),
  ('Mısır tanelerindeki benekli renk desenlerini inceleyerek kromozom üzerinde yer değiştirebilen genetik elemanları keşfeden ve 1983\'te Nobel ödülü alan bilim insanı kimdir?', 'B. McClintock', ['Rosalind Franklin', 'Nettie Stevens', 'Gertrude Elion'], 'McClintock 1940\'larda mısırda "sıçrayan genleri" (transpozonları) keşfetti; çalışmaları uzun süre ilgi görmedi ve 1983\'te tek başına Nobel aldı.'),
  ('Bir genomda bir yerden kesilip başka bir yere yerleşebilen DNA dizilerine genel olarak ne ad verilir?', 'Transpozon', ['Operatör', 'Promotör', 'İntron'], 'Transpozonlar (hareketli genetik elemanlar) transpozaz gibi enzimler yardımıyla genom içinde yer değiştirebilir.'),
  ('Bir transpozonun bir genin kodlayan bölgesinin içine yerleşmesinin en olası sonucu nedir?', 'Genin işlevini bozan bir mutasyon oluşması', ['Genin iki katına çıkarak daha çok protein üretmesi', 'Hücrenin haploit hâle gelmesi', 'Genin mitokondriye taşınması'], 'Araya giren dizi okuma çerçevesini bozabilir ya da dur kodonu getirebilir; McClintock\'un mısır tanelerindeki renk kayıpları da böyle oluşuyordu.'),
  ('Önce RNA\'ya kopyalanıp ters transkriptazla yeniden DNA\'ya çevrilerek genomun başka bir yerine yerleşen hareketli elemanlara ne ad verilir?', 'Retrotranspozon', ['Plazmit', 'Bakteriyofaj', 'Kozmit vektörü'], 'Retrotranspozonlar "kopyala-yapıştır" yöntemiyle çoğalır; asıl kopya yerinde kalır, bu yüzden genomda birikirler.'),
  ('E. coli kromozomunda DNA eşlenmesinin başladığı tek özgül bölgeye ne ad verilir?', 'oriC', ['Operatör', 'TATA kutusu', 'Sentromer'], 'Bakterinin halkasal kromozomunda tek bir eşlenme başlangıç noktası (oriC) bulunur; eşlenme buradan iki yöne ilerler.'),
  ('Eşlenme sırasında açılmış tek zincirli DNA bölgelerine bağlanarak zincirlerin yeniden eşleşmesini ve kendi üzerine katlanmasını önleyen proteinlere ne ad verilir?', 'Tek zincir bağlayıcı proteinler', ['Histon benzeri paketleme proteinleri ve topoizomerazlar', 'Restriksiyon enzimleri', 'Salınma faktörleri'], 'SSB proteinleri açılmış zincirleri kaplayarak polimerazın kalıbı okuyabileceği düz bir hâlde tutar.'),
  ('Bir eşlenme başlangıç noktasından itibaren iki eşlenme çatalının zıt yönlere ilerlemesiyle oluşan, elektron mikroskobunda göz biçiminde görülen yapıya ne ad verilir?', 'Eşlenme kabarcığı', ['Nükleozom', 'Okazaki parçası', 'Kiazma'], 'Çatallar iki yöne ilerledikçe arada açılmış ve kopyalanmış bir bölge oluşur; buna eşlenme kabarcığı (gözü) denir.'),
  ('Öncü (sürekli) zincirin sentezi için hangisi doğrudur?', 'Eşlenme çatalının ilerleme yönünde tek bir primerden başlayarak kesintisiz sentezlenir.', ['Çatala ters yönde kısa parçalar hâlinde sentezlenir.', '3\'→5\' yönünde sentezlenir.', 'Primer gerektirmeden sentezlenir.'], 'Öncü zincirin 3\' ucu çatala doğru baktığından polimeraz çatalı izleyerek tek primerle kesintisiz ilerleyebilir.'),
  ('Eşlenme sırasında çalışan enzimler ilk görev aldıkları sıraya göre dizilirse hangi sıralama doğru olur?', 'Helikaz → primaz → polimeraz → ligaz', ['Primaz → ligaz → helikaz → DNA polimeraz', 'DNA polimeraz → helikaz → ligaz → primaz', 'Ligaz → DNA polimeraz → primaz → helikaz'], 'Önce sarmal açılır, primer yapılır, polimeraz zinciri uzatır ve en son parçalar ligazla birleştirilir.'),
  ('Kanser hücrelerinin büyük çoğunluğunda telomeraz enziminin etkin olması, bu hücrelerin hangi özelliğine katkıda bulunur?', 'Telomer kısalmasına uğramadan sınırsız bölünebilmelerine', ['Oksijensiz ortamda hiçbir koşulda yaşayamamalarına ve hızla ölmelerine', 'Kromozom sayılarının yarıya inmesine', 'Bağışıklık sistemine görünmez olmalarına'], 'Telomeraz telomerleri yeniden uzattığından kanser hücreleri Hayflick sınırına takılmadan bölünmeye devam eder; bu nedenle telomeraz bir ilaç hedefidir.'),
  ('Telomeraz etkinliğinin yetişkin insanda hangi hücrelerde yüksek, çoğu vücut hücresinde ise çok düşük olması beklenir?', 'Eşey ana hücreleri ve kök hücrelerde', ['Olgun alyuvarlarda ve kan pulcuklarında', 'Sinir hücrelerinde', 'Yağ hücrelerinde'], 'Sürekli bölünmesi gereken eşey hattı ve kök hücreleri telomerlerini korumak için telomeraz kullanır; farklılaşmış somatik hücrelerin çoğunda enzim etkin değildir.'),
  ('DNA\'daki sitozin bazının kendiliğinden amin grubunu kaybetmesi (deaminasyon) sonucunda hangi baz oluşur?', 'Urasil', ['Timin', '5-metilsitozin', 'Adenin'], 'Sitozinin deaminasyonu urasil oluşturur; onarılmazsa sonraki eşlenmede karşısına A gelir ve G-C çifti A-T\'ye dönüşür.'),
  ('İyonlaştırıcı radyasyonun (X ve gama ışınları) DNA\'da oluşturduğu en tehlikeli hasar türü hangisidir?', 'Çift zincir kırıkları', ['Timin dimerleri', 'Sitozin metilasyonu', 'Hidrojen bağlarının geçici açılması'], 'İyonlaştırıcı radyasyon iki zinciri birden kırabilir; onarılmayan çift zincir kırıkları kromozom kayıplarına ve yeniden düzenlemelere yol açar.'),
  ('DNA onarım mekanizmaları üzerine çalışmalarıyla 2015 Nobel Kimya Ödülü\'nü Tomas Lindahl ve Paul Modrich ile paylaşan Türk bilim insanı kimdir?', 'Aziz Sancar', ['Gazi Yaşargil', 'Feza Gürsey', 'Cahit Arf'], 'Aziz Sancar nükleotit kesip çıkarma onarımı ve fotoliyaz üzerine çalışmalarıyla 2015 Nobel Kimya Ödülü\'nü paylaştı.'),
  ('2015 Nobel Kimya Ödülü\'nde Aziz Sancar\'ın aydınlattığı onarım yolu hangisidir?', 'Nükleotit kesip çıkarma onarımı', ['Baz kesip çıkarma onarımı', 'Eşleşmeme (yanlış eşleşme) onarımı', 'Homolog olmayan uç birleştirme'], 'Sancar, UV hasarının nükleotit kesip çıkarma onarımıyla nasıl giderildiğini gösterdi; Lindahl baz kesip çıkarma, Modrich ise eşleşmeme onarımı üzerine çalıştı.'),
  ('Bir hücrede DNA hasarı çok fazla ve onarılamaz düzeydeyse sağlıklı bir dokuda beklenen sonuç hangisidir?', 'Hücrenin programlı ölüme (apoptoz) gitmesi', ['Hücrenin daha hızlı bölünmesi', 'Hasarın yavru hücrelere eşit paylaştırılması', 'Hücrenin çekirdeğini atarak yaşamaya devam etmesi'], 'Onarılamayan hasar, mutasyonların aktarılmasını önlemek için apoptozu tetikler; bu yanıtın bozulması kansere zemin hazırlar.'),
  ('Bir gendeki tek baz değişikliği sonucu bir kodonun farklı bir amino asidi kodlamasına ne ad verilir?', 'Yanlış anlamlı (missense) mutasyon', ['Çerçeve kayması mutasyonu', 'Sessiz mutasyon', 'Kromozom duplikasyonu'], 'Tek baz değişimi kodonu başka bir amino aside dönüştürüyorsa buna yanlış anlamlı mutasyon denir; orak hücre anemisi bunun bilinen örneğidir.'),
  ('Huntington hastalığında huntingtin genindeki CAG üçlüsü tekrar sayısının artması proteinde hangi değişikliğe yol açar?', 'Uzun bir glutamin dizisinin oluşmasına', ['Proteinin hiç sentezlenmemesine', 'Proteindeki bütün amino asitlerin sırasının tersine dönmesine', 'Proteinin RNA\'ya dönüşmesine'], 'CAG glutamini kodlar; tekrar sayısı yaklaşık 36\'yı aştığında proteinde uzamış bir poliglutamin bölgesi oluşur ve sinir hücrelerine zarar verir.'),
  ('Bir mutasyonla işlevini yitirmiş bir genin, ikinci bir mutasyonla özgün dizisine dönerek yeniden işlev kazanmasına ne ad verilir?', 'Geri mutasyon', ['Sessiz mutasyon', 'Somatik mutasyon', 'Nötr mutasyon'], 'Geri (ters) mutasyon ilk değişikliği ortadan kaldırarak yabanıl fenotipi yeniden ortaya çıkarır.'),
  ('Bazı meme kanserlerinde HER2 adlı büyüme faktörü reseptörü geninin hücrede çok sayıda kopyasının bulunduğu saptanır. Bu gen amplifikasyonunun doğrudan sonucu nedir?', 'Reseptör proteininin aşırı miktarda üretilmesi', ['Reseptör geninin tamamen susturulması', 'Hücrenin bütün kromozomlarının iki katına çıkması', 'Reseptör proteininin amino asit dizisinin değişmesi'], 'Gen kopya sayısı arttıkça aynı protein daha çok üretilir; HER2 fazlalığı bölünme sinyalini güçlendirir ve bu reseptöre bağlanan trastuzumab gibi antikorlar tedavide kullanılır.'),
  ('Bakterilerde RNA polimerazın promotörü tanıyıp doğru yerden transkripsiyonu başlatmasını sağlayan alt birim hangisidir?', 'Sigma (σ) faktörü', ['Rho (ρ) faktörü', 'Salınma faktörü', 'Kayan kıskaç'], 'Sigma faktörü çekirdek enzime bağlanarak promotördeki -10 ve -35 bölgelerini tanımasını sağlar; transkripsiyon başladıktan sonra ayrılır.'),
  ('Transkripsiyonda RNA polimerazın kalıp zinciri okuma yönü ve sentezlenen RNA\'nın uzama yönü için hangisi doğrudur?', 'Kalıp 3\'→5\' yönünde okunur, RNA 5\'→3\' yönünde uzar.', ['Kalıp 5\'→3\' yönünde okunur, RNA 5\'→3\' yönünde uzar.', 'Kalıp 3\'→5\' yönünde okunur, RNA 3\'→5\' yönünde uzar.', 'Kalıp iki yönde de okunur, RNA da iki yönde uzar.'], 'Antiparalel eşleşme nedeniyle RNA\'nın 5\'→3\' uzaması için kalıp zincir 3\'→5\' yönünde okunmalıdır.'),
  ('Bir genin promotörüne göre transkripsiyon yönündeki dizilere "aşağı akım", ters yöndekilere "yukarı akım" denir. Başlama noktası +1 kabul edildiğinde -35 bölgesi için hangisi doğrudur?', 'Başlama noktasının yukarı akımında, 35 nükleotit gerisindedir.', ['Başlama noktasının aşağı akımında, kodlanan bölgenin içindedir.', 'mRNA\'nın 3\' ucunda yer alır.', 'Genin son kodonunun hemen arkasındadır.'], 'Eksi işaretli konumlar transkripsiyonun başladığı noktadan önceki, kopyalanmayan yukarı akım dizilerini gösterir.'),
  ('Ökaryot promotörlerinin çoğunda başlama noktasının yaklaşık 25–30 nükleotit gerisinde bulunan ve TATA bağlayıcı proteinin tutunduğu dizi hangisidir?', 'TATA kutusu', ['Pribnow kutusu', 'Kozak dizisi', 'Poli-A sinyali'], 'TATA kutusu ökaryotik genel transkripsiyon faktörlerinin, özellikle TFIID\'nin bağlandığı temel promotör ögesidir.'),
  ('Ökaryotlarda RNA polimeraz II\'nin promotöre bağlanabilmesi için önce promotörde toplanması gereken proteinlere ne ad verilir?', 'Genel transkripsiyon faktörleri', ['Histon deasetilazlar', 'Aminoasil-tRNA sentetaz enzimleri', 'Restriksiyon enzimleri'], 'Bakteri polimerazından farklı olarak RNA polimeraz II promotörü tek başına tanıyamaz; TFIID, TFIIB gibi genel faktörlerle birlikte başlama kompleksi oluşturur.'),
  ('Bir gen aynı anda birden çok RNA polimeraz tarafından art arda kopyalanabilir. Bu durumun hücreye sağladığı yarar nedir?', 'Kısa sürede aynı genden çok sayıda RNA üretilebilmesi', ['Genin her kopyalanışta farklı bir proteini kodlaması ve çeşitlilik sağlaması', 'Kalıp zincirin her seferinde değişmesi', 'DNA\'nın kendiliğinden onarılması'], 'Özellikle rRNA genlerinde onlarca polimeraz aynı geni aynı anda kopyalar; elektron mikroskobunda "Noel ağacı" görüntüsü oluşur.'),
  ('Ökaryotik mRNA\'daki 5\' kep yapısının işlevlerinden biri hangisidir?', 'mRNA\'yı yıkımdan korumak ve ribozomun mRNA\'ya bağlanmasına yardım etmek', ['mRNA\'yı DNA\'ya geri çevirmek', 'Translasyonu sonlandıran dur kodonu görevi görmek', 'İntronları kesip çıkarmak'], 'Kep 5\' ekzonükleazlara karşı koruma sağlar ve küçük ribozom alt biriminin mRNA\'yı tanımasında rol oynar.'),
  ('Poli-A kuyruğu ile ilgili hangisi doğrudur?', 'DNA\'da kodlanmaz, şablon gerektirmeyen bir enzimle sonradan eklenir.', ['Genin sonundaki uzun timin dizisinin RNA polimerazca kalıp olarak kopyalanmasıyla oluşur.', 'Bakteri mRNA\'larının tamamında uzun ve kalıcıdır.', 'Ribozomda amino asit olarak lizin zincirine çevrilir.'], 'Poli(A) polimeraz kalıp kullanmadan adenin ekler; kuyruğun kısalması mRNA\'nın ömrünün azalmasıyla ilişkilidir.'),
  ('Olgun bir mRNA\'da başlama kodonundan önceki ve dur kodonundan sonraki, proteine çevrilmeyen bölgelere ne ad verilir?', '5\' ve 3\' çevrilmeyen bölgeler (UTR)', ['İntronlar', 'Promotör ve operatör bölgeleri (kontrol dizileri)', 'Okazaki parçaları'], 'UTR\'ler olgun mRNA\'da kalır ama amino asit kodlamaz; translasyonun düzeyini ve mRNA\'nın ömrünü düzenleyen diziler içerir.'),
  ('Kırpılma kompleksinin (splisozom) yapısına katılan küçük çekirdek RNA\'ları hangi kısaltmayla anılır?', 'snRNA', ['miRNA', 'tRNA', 'Mitokondriyal tRNA'], 'snRNA\'lar (U1, U2 vb.) proteinlerle snRNP\'leri oluşturur ve intron sınırlarını baz eşleşmesiyle tanır.'),
  ('Hücrede toplam RNA kütlesinin en büyük kısmını genellikle hangi RNA türü oluşturur?', 'rRNA', ['mRNA', 'snRNA', 'miRNA'], 'rRNA hücredeki RNA\'nın yaklaşık %80\'ini oluşturur; mRNA yalnızca birkaç yüzdedir.'),
  ('tRNA moleküllerinin iki boyutlu çizimlerde benzetildiği yaprak biçimi ve gerçek üç boyutlu biçimi hangi seçenekte doğru verilmiştir?', 'Yonca yaprağı; L harfi biçimi', ['Çam iğnesi; düz çubuk biçimi', 'Kalp; küre biçimi', 'Yonca yaprağı; çift sarmal halka'], 'tRNA kendi içinde baz eşleşmeleriyle yonca yaprağı biçiminde katlanır; üç boyutta bu yapı L harfine benzeyen bir biçim alır.'),
  ('Genetik kodun ikişerli nükleotitlerden oluşamayacağı basit bir hesapla gösterilebilir. Bu hesabın dayanağı hangisidir?', 'İkili birimlerle yalnızca 16 farklı kombinasyon oluşur ve bu, 20 amino asit için yetersizdir.', ['İkili birimlerle 64 kombinasyon oluşur ve bu sayı 20 amino asit için gereğinden çok fazladır.', 'Nükleotitlerin yalnızca ikisi amino asit kodlayabilir.', 'İkili birimler ribozoma sığmaz.'], '4² = 16 < 20 olduğundan en az üçlü birim gerekir; 4³ = 64 ise yeterlidir.'),
  ('Genetik kodun "örtüşmeyen" olması ne anlama gelir?', 'Her nükleotit yalnızca bir kodonun parçası olarak okunur.', ['Her amino asit yalnızca bir kodonla kodlanır.', 'Kodonlar arasında okunmadan atlanan, boşluk görevi gören nükleotitler bulunur.', 'İki zincir aynı anda okunur.'], 'Örneğin AUGCCC dizisi AUG ve CCC olarak okunur; UGC gibi üst üste binen üçlüler okunmaz.'),
  ('Standart genetik kodda yalnızca tek bir kodonla belirlenen iki amino asit hangileridir?', 'Metiyonin ve triptofan', ['Lösin ve serin', 'Glisin, alanin ve valin', 'Arjinin ve lizin'], 'Metiyonin yalnızca AUG, triptofan yalnızca UGG ile kodlanır.'),
  ('64 kodondan kaçı bir amino asidi belirleyen anlamlı kodondur?', '61', ['64', '60', '20'], 'Üç dur kodonu (UAA, UAG, UGA) dışındaki 61 kodon amino asit kodlar.'),
  ('Bir mRNA dizisi için olası okuma çerçevesi sayısı kaçtır?', '3', ['1', '6', '64'], 'Okuma birinci, ikinci ya da üçüncü nükleotitten başlayabilir; tek zincirli mRNA için üç okuma çerçevesi vardır. Çift zincirli DNA için bu sayı altıdır.'),
  ('Bir DNA dizisinde başlama kodonuyla başlayan ve aynı çerçevede bir dur kodonuna kadar kesintisiz uzanan, protein kodlama olasılığı bulunan bölgeye ne ad verilir?', 'Açık okuma çerçevesi', ['Operatör bölgesi', 'Telomer bölgesi', 'Çevrilmeyen 3\' bölgesi'], 'Açık okuma çerçevesi (ORF) arayışı, yeni dizilenmiş genomlarda gen bulmanın temel yöntemlerinden biridir.'),
  ('mRNA\'da 5\'-AUGUUUGGCUAA-3\' dizisi bulunuyor. AUG = metiyonin, UUU = fenilalanin, GGC = glisin ve UAA = dur olduğuna göre sentezlenen peptidin dizisi hangisidir?', 'Met-Phe-Gly', ['Met-Gly-Phe', 'Phe-Gly-Met', 'Met-Phe-Gly-Dur-Met'], 'Kodonlar sırayla AUG, UUU, GGC, UAA okunur; dur kodonu amino asit eklemez.'),
  ('Bakteri mRNA\'larında başlama kodonunun birkaç nükleotit önünde bulunan ve küçük ribozom alt birimindeki 16S rRNA ile eşleşerek ribozomu doğru konuma yerleştiren dizi hangisidir?', 'Shine-Dalgarno dizisi', ['TATA kutusu', 'Poli-A sinyali', 'Kozak uzlaşı dizisi'], 'Shine-Dalgarno dizisi (uzlaşı AGGAGG) 16S rRNA\'nın 3\' ucuyla baz eşleşmesi yaparak AUG\'nin P bölgesine gelmesini sağlar.'),
  ('Bakterilerde translasyonu başlatan tRNA hangi amino asidi taşır?', 'N-formilmetiyonin', ['Triptofan', 'Glisin', 'Selenosistein'], 'Bakterilerde başlatıcı tRNA formil grubu eklenmiş metiyonin (fMet) taşır; ökaryotlarda başlatıcı amino asit formilsiz metiyonindir.'),
  ('Translasyonun başlama aşamasında başlatıcı tRNA ribozomun hangi bölgesine yerleşir?', 'P bölgesi', ['A bölgesi', 'E bölgesi', 'Büyük alt birimin dışına'], 'Başlatıcı tRNA doğrudan P bölgesine yerleşir; sonraki bütün aminoasil-tRNA\'lar A bölgesine gelir.'),
  ('Ribozomdaki A, P ve E bölgelerinin görevleri hangi seçenekte doğru eşleştirilmiştir?', 'A: yeni aminoasil-tRNA girer; P: büyüyen zinciri taşıyan tRNA durur; E: boşalmış tRNA çıkar.', ['A: boşalmış tRNA çıkar; P: yeni tRNA girer; E: peptit bağı kurulur.', 'A: mRNA bağlanır; P: protein katlanır; E: amino asit sentezlenir.', 'A: dur kodonu okunur; P: 5\' kep tanınır ve bağlanır; E: intronlar kesilip ribozomdan çıkarılır.'], 'Aminoasil (A), peptidil (P) ve çıkış (exit, E) bölgeleri tRNA\'nın ribozomdaki ardışık duraklarıdır.'),
  ('Translasyonda ribozomun mRNA üzerinde ilerleme yönü ve polipeptidin sentez yönü hangi seçenekte doğru verilmiştir?', 'mRNA 5\'→3\' yönünde okunur; zincir amino ucundan karboksil ucuna doğru uzar.', ['mRNA 3\'→5\' yönünde okunur; zincir karboksil ucundan amino ucuna uzar.', 'mRNA 5\'→3\' yönünde okunur; zincir karboksil ucundan amino ucuna uzar.', 'mRNA aynı anda iki yönde okunur; zincir hem amino hem karboksil ucundan eşit hızla uzar.'], 'İlk amino asit serbest amino (N) ucunu oluşturur; her yeni amino asit karboksil (C) ucuna eklenir.'),
  ('Yeni sentezlenen proteinlerin doğru katlanmasına yardım eden ve yanlış katlanmış proteinlerin kümelenmesini önleyen proteinlere ne ad verilir?', 'Şaperonlar', ['Histonlar', 'Restriksiyon enzimleri', 'Telomerazlar'], 'Şaperonlar (örneğin Hsp70, Hsp60) katlanmayı kolaylaştırır; ısı stresinde miktarları arttığı için "ısı şoku proteinleri" olarak da anılırlar.'),
  ('Hücrede yıkılması gereken proteinlere küçük bir protein zinciri eklenerek bunların parçalayıcı komplekse yönlendirilmesi sürecinde eklenen işaret protein hangisidir?', 'Ubikuitin', ['Histon H1', 'Kalmodulin', 'Albümin'], 'Ubikuitin zinciri eklenen proteinler proteazom tarafından tanınıp küçük peptitlere parçalanır.'),
  ('Ubikuitinle işaretlenen proteinleri ATP harcayarak parçalayan, fıçı biçimli büyük protein kompleksine ne ad verilir?', 'Proteazom', ['Lizozom', 'Nükleozom kompleksi', 'Splisozom'], 'Proteazom sitoplazma ve çekirdekte bulunan, işaretli proteinleri yıkan bir proteaz kompleksidir.'),
  ('Bir proteinin belirli serin, treonin ya da tirozin amino asitlerine kinaz enzimleriyle fosfat grubu eklenmesi genellikle hangi amaca hizmet eder?', 'Proteinin etkinliğini hızlı ve geri dönüşebilir biçimde açıp kapamak', ['Proteini kalıcı olarak DNA\'ya dönüştürmek', 'Proteinin amino asit dizisini kalıcı olarak değiştirip yeni bir gen oluşturmak', 'Proteini hücreden kesinlikle uzaklaştırmak'], 'Fosforilasyon proteinin biçimini ve etkinliğini değiştirir; fosfatazlar grubu uzaklaştırarak etkiyi tersine çevirir.'),
  ('İnsülin önce tek zincirli proinsülin olarak sentezlenir, sonra iç kısmındaki C-peptit kesilip çıkarılarak iki zincirli olgun hormon oluşur. Bu süreç neyin örneğidir?', 'Translasyon sonrası kesimle etkinleştirmenin', ['Alternatif kırpılmayla iki farklı protein üretilmesinin', 'RNA düzenlemenin', 'Gen amplifikasyonunun'], 'Olgun insülinin A ve B zincirleri disülfit köprüleriyle bağlı kalır; aradaki C-peptidin kesilmesi translasyondan sonra gerçekleşen bir işlemdir.'),
  ('Zar ve salgı proteinlerine endoplazmik retikulum ve Golgi\'de şeker zincirleri eklenmesine ne ad verilir?', 'Glikozilasyon', ['Metilasyon', 'Fosforilasyon', 'Asetilasyon'], 'Glikozilasyon proteinlerin katlanmasına, kararlılığına ve hücreler arası tanınmaya katkıda bulunur; ABO kan grubu antijenleri de şeker zincirleriyle belirlenir.'),
  ('Gen ifadesi kavramı en doğru hangi seçenekte tanımlanmıştır?', 'Bir gendeki bilginin RNA ve çoğunlukla protein gibi işlevsel bir ürüne dönüştürülmesi', ['Bir genin mutasyona uğrayarak yeni bir alel oluşturması', 'Bir genin eşlenme sırasında kopyalanması', 'Bir genin bir kromozomdan diğerine taşınarak farklı bir hücre tipinde etkin hâle gelmesi'], 'Gen ifadesi transkripsiyonu ve (protein kodlayan genler için) translasyonu kapsar; düzenlenmesi hücrenin hangi proteinleri üreteceğini belirler.'),
  ('Lac operonundaki lacZ geninin kodladığı ve laktozu glikoz ile galaktoza parçalayan enzim hangisidir?', 'β-galaktozidaz', ['Laktoz permeaz', 'Transasetilaz', 'DNA ligaz'], 'lacZ β-galaktozidazı, lacY laktozun hücreye alınmasını sağlayan permeazı, lacA ise transasetilazı kodlar.'),
  ('Bakterilerde aynı metabolik yolda görev yapan genlerin tek bir operonda bir araya toplanmasının avantajı nedir?', 'İlgili enzimlerin tek bir düzenleyici sinyalle eş zamanlı açılıp kapanabilmesi', ['Her genin ayrı bir promotörle bağımsız okunabilmesi', 'Genlerin mutasyondan tamamen korunması', 'Bakterinin kromozom sayısının azalması ve bölünmenin hızlanması'], 'Operondaki genler ortak bir mRNA\'da kopyalandığından bir yolun bütün enzimleri birlikte ve eşit oranda üretilebilir.'),
  ('Gen düzenlemesinde "negatif kontrol" ile "pozitif kontrol" arasındaki fark hangisidir?', 'Negatif kontrolde bağlanan protein transkripsiyonu engeller, pozitif kontrolde ise artırır.', ['Negatif kontrol yalnızca ökaryotlarda, pozitif kontrol yalnızca bakterilerde görülür.', 'Negatif kontrolde ilgili gen DNA\'dan silinir, pozitif kontrolde ise kopya sayısı artırılarak çoğaltılır.', 'Negatif kontrol RNA\'yı, pozitif kontrol proteini hedefler.'], 'Lac baskılayıcısı negatif, cAMP-CAP kompleksi ise RNA polimerazın bağlanmasını kolaylaştırdığı için pozitif kontrol örneğidir.'),
  ('cAMP-CAP kompleksinin lac promotörüne bağlanması transkripsiyonu nasıl etkiler?', 'RNA polimerazın promotöre bağlanmasını kolaylaştırarak transkripsiyonu artırır.', ['Baskılayıcıyı operatöre sıkıca bağlar.', 'mRNA\'yı yıkarak translasyonu durdurur.', 'Laktozun hücreye girişini engelleyerek operonu glikoz bitene kadar kapalı tutar.'], 'CAP bir aktivatördür; glikoz azaldığında artan cAMP\'ye bağlanır ve promotörün yakınına tutunarak polimerazı çeker.'),
  ('Bir araştırmacı belirli bir proteini kodlayan genin bir dokuda transkripsiyon düzeyinde etkin olup olmadığını öğrenmek istiyor. Bunun için o dokuda hangisinin varlığını araştırması en doğrudan kanıtı sağlar?', 'O gene ait mRNA\'nın', ['O genin DNA dizisinin', 'Genin bulunduğu kromozomun sentromerinin', 'Hücredeki toplam rRNA ve tRNA miktarının'], 'Gen DNA\'sı bütün hücrelerde bulunduğundan ifade kanıtı olamaz; genin mRNA\'sının bulunması transkripsiyonun gerçekleştiğini doğrudan gösterir.'),
  ('Ökaryotlarda bir genin transkripsiyonunu azaltan ve baskılayıcı proteinlerin bağlandığı uzak DNA dizilerine ne ad verilir?', 'Susturucu (silencer)', ['Güçlendirici (enhancer)', 'Promotör', 'Operatör'], 'Susturucular, güçlendiricilerin tersine, bağlanan baskılayıcı proteinler aracılığıyla transkripsiyonu engeller.'),
  ('Ökaryotlarda bir hücrenin her zaman ve her dokuda ifade ettiği, glikoliz enzimleri ya da ribozom proteinleri gibi temel işlevlerden sorumlu genlere ne ad verilir?', 'Ev idaresi (housekeeping) genleri', ['Onkogenler', 'İşlevsiz psödogen kopyaları', 'Homeotik gelişim genleri'], 'Bu genler hücrenin yaşamı için sürekli gereklidir; gen ifadesi deneylerinde karşılaştırma ölçütü olarak da kullanılırlar.'),
  ('Dişi memeli embriyosunda X kromozomu inaktivasyonu için hangisi doğrudur?', 'Erken embriyoda her hücrede bir X rastgele susturulur; seçim yavru hücrelere aktarılır.', ['Her zaman babadan gelen X kromozomu bütün hücrelerde aynı anda ve kalıcı olarak susturulur.', 'İnaktivasyon ergenlikte başlar ve her hücre bölünmesinde yeniden rastgele seçilir.', 'Susturulan X kromozomu hücreden atılır.'], 'Rastgele ve kalıcı seçim nedeniyle dişi bireyler iki farklı hücre topluluğundan oluşan bir mozaik gibi davranır.'),
  ('Mikro RNA\'ları keşfederek ve bunların gen düzenlemesindeki rolünü ortaya koyarak 2024 Nobel Fizyoloji veya Tıp Ödülü\'nü alan bilim insanları kimlerdir?', 'Victor Ambros ve Gary Ruvkun', ['Andrew Fire ve Craig Mello', 'Katalin Karikó ve Drew Weissman', 'Svante Pääbo ve Jack Szostak'], 'Ambros ve Ruvkun 1993\'te C. elegans\'ta lin-4 adlı küçük RNA\'nın lin-14 mRNA\'sına bağlanarak çevrilmesini baskıladığını gösterdi.'),
  ('Bakterilerde genetik maddenin bir bakteriyofaj aracılığıyla bir bakteriden diğerine taşınmasına ne ad verilir?', 'Transdüksiyon', ['Konjugasyon', 'Transformasyon', 'Translokasyon'], 'Faj paketlenirken yanlışlıkla konak DNA\'sının bir parçasını alır ve yeni enfekte ettiği bakteriye aktarır; buna transdüksiyon denir.'),
  ('İki bakteri hücresinin bir pilus aracılığıyla temas kurup birinden diğerine DNA (çoğunlukla plazmit) aktarmasına ne ad verilir?', 'Konjugasyon', ['Transdüksiyon', 'Transkripsiyon', 'Sporlanma'], 'Konjugasyonda verici hücre F plazmidi gibi bir plazmidin kopyasını alıcıya aktarır; doğrudan hücre teması gerekir.'),
  ('Konjugasyonda yalnızca F plazmidi taşıyan (F⁺) hücreler pilus oluşturup verici olabilir. Bir F⁺ hücre bir F⁻ hücreyle konjugasyona girdikten sonra alıcı hücrenin durumu genellikle ne olur?', 'F⁺ hâline gelir ve kendisi de verici olabilir.', ['F⁻ olarak kalır ve plazmidi hemen yıkar.', 'Ölür ve içeriğini vericiye besin olarak bırakarak onun bölünmesini hızlandırır.', 'Kromozomunun tamamını kaybeder.'], 'F plazmidinin tek zinciri aktarılır, iki hücrede de tamamlayıcı zincir sentezlenir; böylece alıcı F⁺ olur.'),
  ('Restriksiyon enzimlerinin bakterilerdeki doğal görevi nedir?', 'Hücreye giren yabancı (örneğin faj) DNA\'yı kesip etkisizleştirmek', ['Bakterinin kendi kromozomunu bölünmede ikiye ayırmak', 'Bakteri hücre duvarındaki hasarlı peptidoglikan bölgelerini onarmak', 'Plazmitleri birbirine bağlamak'], 'Bu enzimler fajların çoğalmasını "kısıtladıkları" (restrict) için bu adı almıştır; bir tür ilkel bağışıklık sistemi gibi çalışırlar.'),
  ('Bir bakteri kendi restriksiyon enziminin tanıma dizilerini kendi kromozomunda da taşır. Kendi DNA\'sının kesilmesini nasıl önler?', 'Bu dizilerdeki bazları bir metilaz enzimiyle metilleyerek', ['Kromozomunu hücre zarının dışında tutarak', 'Restriksiyon enzimini yalnızca bölünme sırasında üreterek', 'Kromozomunu geçici olarak RNA\'ya dönüştürüp enzimden saklayarak'], 'Restriksiyon-modifikasyon sisteminde eş metilaz kendi DNA\'sındaki tanıma dizilerini işaretler; metillenmiş diziler enzimce kesilmez.'),
  ('Restriksiyon enzimleri farklı tiplere ayrılır. Gen mühendisliğinde en çok II. tip restriksiyon enzimlerinin kullanılmasının nedeni hangisidir?', 'Tanıma dizisinin içinden ya da hemen yanından, her seferinde aynı noktadan kesmeleri', ['Tanıma dizisinden binlerce baz uzaktaki rastgele noktalardan kesmeleri', 'Yalnızca RNA\'yı kesebilmeleri', 'DNA\'yı kesmeden yalnızca metilleyerek işaretlemeleri ve bu işaretlerin kalıcı olması'], 'II. tip enzimler belirli bir diziyi tanıyıp kesin bir noktadan keser; bu nedenle her seferinde aynı parçaları üretirler. Diğer tiplerin kesim yeri değişkendir.'),
  ('Restriksiyon enzimlerinin adlandırılmasında EcoRI adındaki "Eco" neyi gösterir?', 'Enzimin elde edildiği bakteri türünü', ['Enzimin tanıdığı dizinin uzunluğunu', 'Enzimin çalıştığı sıcaklığı', 'Enzimin keşfedildiği ülkeyi ve laboratuvarın adının kısaltmasını'], 'İlk harf cinsi, sonraki iki harf türü gösterir (E. coli); R suşu, Romen rakamı ise o türden bulunan enzimin sırasını belirtir.'),
  ('Doğrusal, 10.000 baz çiftlik bir DNA molekülü yalnızca üç noktadan kesen bir restriksiyon enzimiyle tamamen kesiliyor. Kaç DNA parçası oluşur?', '4', ['3', '6', '2'], 'Doğrusal bir molekülde n kesim n + 1 parça oluşturur: 3 + 1 = 4.'),
  ('Klonlama plazmitlerinde birçok farklı restriksiyon enziminin tek kesim yerinin art arda dizildiği kısa bölgeye ne ad verilir?', 'Çoklu klonlama bölgesi (polilinker)', ['Eşlenme başlangıcı', 'Promotör', 'Seçici işaret geni (antibiyotik direnci)'], 'Çoklu klonlama bölgesi, araştırıcıya yabancı DNA\'yı eklemek için uygun enzimi seçme esnekliği verir.'),
  ('Bir plazmidin bakteri bölündükçe çoğalabilmesi ve yavru hücrelere aktarılabilmesi için hangi dizinin bulunması zorunludur?', 'Eşlenme başlangıcı', ['Poli-A sinyali', 'Telomer dizisi', 'Kozak dizisi ve kep bölgesi'], 'ori, konak hücrenin eşlenme enzimlerinin plazmidi kopyalamaya başladığı bölgedir; olmazsa plazmit bölünmelerde seyrelip kaybolur.'),
  ('1973\'te restriksiyon enzimleriyle kesilip birleştirilen plazmitleri E. coli\'ye aktararak yabancı DNA taşıyan plazmitlerin bakteride çoğaltılabildiğini gösteren ve rekombinant DNA teknolojisinin başlangıcı sayılan çalışmayı yapan bilim insanları kimlerdir?', 'Stanley Cohen ve Herbert Boyer', ['James Watson ve Francis Crick', 'Matthew Meselson ve Franklin Stahl', 'Alfred Hershey ve Martha Chase'], 'Cohen ve Boyer\'in 1973 çalışması plazmit ile restriksiyon enzimlerini birleştirdi; ertesi yıl kurbağa DNA\'sının da bu yolla bakteride çoğaltılabildiğini gösterdiler. Boyer daha sonra Genentech\'i kurdu.'),
  ('Transgenik fare üretiminde yabancı DNA\'nın döllenmiş yumurtanın erkek pronükleusuna ince bir cam iğneyle doğrudan verilmesine ne ad verilir?', 'Mikroenjeksiyon', ['Elektroforez', 'Transdüksiyon', 'Hibridizasyon'], 'Mikroenjeksiyonla verilen DNA bazı zigotlarda kromozoma yerleşir; bu zigotlardan gelişen fareler geni bütün hücrelerinde taşır.'),
  ('Kalın hücre duvarı nedeniyle gen aktarımı zor olan bitki hücrelerine, DNA kaplı altın ya da tungsten parçacıklarının yüksek hızla gönderilmesi yöntemine ne ad verilir?', 'Gen tabancası', ['Mikroenjeksiyon', 'Konjugasyon', 'Lipozom füzyonu'], 'Gen tabancası parçacıkları hücre duvarından geçirir; DNA\'nın bir kısmı çekirdeğe ulaşıp kromozoma yerleşebilir. Mısır gibi Agrobacterium\'un zor enfekte ettiği bitkilerde kullanılır.'),
  ('DNA\'nın pozitif yüklü yağ kesecikleriyle (lipozomlarla) paketlenip hayvan hücrelerine verilmesinin dayandığı ilke hangisidir?', 'Lipozomun hücre zarıyla kaynaşarak içindeki DNA\'yı hücreye bırakması', ['Lipozomun DNA\'yı RNA\'ya çevirmesi', 'Lipozomun hücre çekirdeğinin zarını kesip açarak DNA\'yı doğrudan kromozoma yerleştirmesi', 'Lipozomun bakteri gibi pilus oluşturması'], 'Katyonik lipitler negatif yüklü DNA\'yı sarar; oluşan kompleks zarla kaynaşır ya da endositozla alınır. mRNA aşılarında da benzer lipit nanoparçacıklar kullanılır.'),
  ('Bir canlının bütün genomunun parçalar hâlinde vektörlere klonlanmasıyla oluşturulan koleksiyona ne ad verilir?', 'Genomik kütüphane', ['cDNA kütüphanesi', 'Popülasyon gen havuzu', 'Karyotip'], 'Genomik kütüphane intronlar ve kodlamayan diziler de dahil genomun tamamını kapsayan klonlardan oluşur.'),
  ('Bir kütüphanede aranan geni bulmak için kullanılan, aranan diziye tamamlayıcı ve işaretlenmiş kısa tek zincirli nükleik asit parçasına ne ad verilir?', 'Prob', ['Primer', 'Vektör', 'Operatör'], 'Prob, radyoaktif ya da floresan işaretlidir; yalnızca tamamlayıcı diziyle eşleştiği için hedef klonu görünür kılar.'),
  ('Bir jelde ayrılan RNA\'ların zara aktarılıp belirli bir mRNA\'nın işaretli probla saptandığı ve bir genin hangi dokuda ifade edildiğini göstermede kullanılan yöntem hangisidir?', 'Northern blot', ['Western blot', 'Southern blot', 'Eastern blot'], 'DNA için Southern, RNA için Northern, protein için Western blot kullanılır; Northern adı Southern\'e benzetilerek verilmiştir.'),
  ('Proteinlerin jelde boyutlarına göre ayrılıp zara aktarılması ve belirli bir proteinin antikorla saptanmasına dayanan yöntem hangisidir?', 'Western blot', ['Northern blot', 'PCR', 'Sanger dizilemesi'], 'Western blot belirli bir proteinin varlığını ve yaklaşık boyutunu gösterir; bazı enfeksiyonların doğrulama testlerinde de kullanılmıştır.'),
  ('Bir cam yüzeye binlerce farklı genin probunun noktalar hâlinde yerleştirildiği ve bir hücrede hangi genlerin hangi düzeyde ifade edildiğini aynı anda ölçmeye yarayan teknoloji hangisidir?', 'DNA mikrodizisi', ['Jel elektroforezi', 'Mikroenjeksiyon', 'Karyotipleme ve bantlama'], 'Hücredeki mRNA\'lardan yapılan floresan işaretli cDNA\'lar çipteki problarla eşleşir; ışıma şiddeti gen ifadesinin ölçüsüdür.'),
  ('PCR döngüsünde zincirlerin ayrılmasından sonra sıcaklığın yaklaşık 50–65°C\'ye düşürülmesinin amacı nedir?', 'Primerlerin kalıp zincirdeki tamamlayıcı dizilere bağlanması', ['Taq polimerazın kalıcı olarak etkisiz hâle getirilip bir sonraki döngüye kadar korunması', 'DNA\'nın yeniden tek zincire ayrılması', 'Nükleotitlerin parçalanıp yeniden sentezlenmesi'], 'Bu basamağa bağlanma (annealing) denir; sıcaklık primerlerin erime sıcaklığına göre seçilir.'),
  ('PCR döngüsünün uzama basamağında sıcaklığın genellikle 72°C\'ye ayarlanmasının nedeni nedir?', 'Taq polimerazın en yüksek etkinliği bu sıcaklıkta göstermesi', ['Primerlerin bu sıcaklıkta kalıptan tamamen ayrılıp karışımdan uzaklaşması', 'DNA\'nın bu sıcaklıkta RNA\'ya dönüşmesi', 'Bu sıcaklıkta hiçbir enzimin çalışmaması'], 'Taq polimeraz, kaynağı olan sıcak su bakterisine uygun olarak yaklaşık 72°C\'de en hızlı çalışır.'),
  ('Bir PCR karışımında aşağıdakilerden hangisinin bulunması gerekmez?', 'RNA polimeraz', ['Kalıp DNA', 'İki primer', 'Dört çeşit deoksinükleotit'], 'PCR\'da kalıp DNA, primerler, dNTP\'ler, ısıya dayanıklı DNA polimeraz ve Mg²⁺ içeren tampon gerekir; RNA polimeraza gerek yoktur.'),
  ('Uzun bir genomun rastgele çok sayıda küçük parçaya bölünüp her parçanın dizilendiği, ardından üst üste binen bölgeler bilgisayarla birleştirilerek tam dizinin elde edildiği yönteme ne ad verilir?', 'Tüm genom shotgun dizilemesi', ['Southern blot analizi', 'Kromozom bantlaması ve karyotip analizi', 'Restriksiyon haritalaması'], 'Shotgun yönteminde parçalar rastgele okunur; örtüşen dizileri birleştirme işi biyoinformatik yazılımlarla yapılır.'),
  ('Biyolojik verilerin, özellikle DNA ve protein dizilerinin bilgisayarlar ve istatistik yöntemlerle depolanması ve çözümlenmesiyle ilgilenen bilim dalına ne ad verilir?', 'Biyoinformatik', ['Biyomekanik', 'Biyocoğrafya ve biyoçeşitlilik', 'Biyofizik'], 'Biyoinformatik dizi karşılaştırma, gen tahmini ve protein yapısı modelleme gibi işleri kapsar.'),
  ('İnsan popülasyonlarında tek bir nükleotit konumunda bireyler arasında görülen yaygın farklılıklara ne ad verilir?', 'Tek nükleotit polimorfizmi (SNP)', ['Çerçeve kayması', 'Trizomi', 'Gen amplifikasyonu (kopya artışı)'], 'SNP\'ler genomdaki en yaygın varyasyon türüdür; hastalık yatkınlığı ve ilaç yanıtı araştırmalarında işaretçi olarak kullanılır.'),
  ('Bir hücre ya da dokuda belirli bir anda üretilen bütün proteinlerin topluca incelenmesine ne ad verilir?', 'Proteomik', ['Genomik', 'Epigenetik', 'Sitogenetik'], 'Genom bütün hücrelerde hemen hemen aynıdır; proteom ise hücre tipine, zamana ve koşullara göre değişir.'),
  ('Bir topraktaki ya da bağırsaktaki mikroorganizmaları laboratuvarda üretmeden, ortamdan doğrudan elde edilen DNA\'nın topluca dizilenmesiyle incelenmesine ne ad verilir?', 'Metagenomik', ['Farmakogenomik', 'Sitogenetik', 'Embriyoloji'], 'Mikroorganizmaların büyük çoğunluğu laboratuvarda üretilemediğinden metagenomik, bu toplulukları tanımanın temel yolu olmuştur.'),
  ('Neandertal genomunu dizileyerek soyu tükenmiş homininlerin genomları ve insan evrimi üzerine çalışmalarıyla 2022 Nobel Fizyoloji veya Tıp Ödülü\'nü alan bilim insanı kimdir?', 'Svante Pääbo', ['Craig Venter', 'Richard Dawkins', 'Allan Wilson'], 'Pääbo eski DNA yöntemlerini geliştirdi, Neandertal genomunu diziledi ve Denisova insanını yalnızca DNA\'sından tanımladı.'),
  ('Rekombinant DNA teknolojisiyle üretilip 1982\'de ABD\'de kullanım onayı alan ilk ilaç hangisidir?', 'İnsan insülini', ['Penisilin', 'Aspirin', 'Kinin'], 'Genentech\'in geliştirdiği ve Eli Lilly\'nin Humulin adıyla pazarladığı bakteri kaynaklı insan insülini, onaylanan ilk rekombinant ilaçtır.'),
  ('Rekombinant insan insülini kullanılmaya başlanmadan önce diyabet hastaları için insülin genellikle hangi kaynaktan elde ediliyordu?', 'Sığır ve domuz pankreasından', ['Bitki köklerinden', 'Maya fermantasyonundan', 'İnsan kanından süzülerek ve damıtılarak'], 'Hayvan insülini birkaç amino asit farklı olduğu için bazı hastalarda bağışıklık tepkisine yol açabiliyordu; rekombinant insülin bu sorunu ve kaynak sınırlılığını ortadan kaldırdı.'),
  ('Böbrek yetmezliği olan hastalarda kansızlığı tedavi etmek için kullanılan rekombinant protein hangisidir?', 'Eritropoietin', ['İnsülin', 'Glukagon', 'Tiroksin'], 'Rekombinant EPO kemik iliğinde alyuvar üretimini uyarır; sporda kötüye kullanımı nedeniyle doping listesinde yer alır.'),
  ('Peynir yapımında geleneksel olarak buzağı midesinden elde edilen kimozin (rennin) enziminin bugün büyük ölçüde nasıl üretildiği aşağıdakilerden hangisidir?', 'Kimozin geni aktarılmış mikroorganizmalarda fermantasyonla', ['Bitki yapraklarından kaynatılarak', 'Yapay olarak amino asitlerden laboratuvarda tek tek birleştirilerek', 'Yalnızca yetişkin ineklerin kanından'], 'Rekombinant kimozin 1990\'da onaylanan ilk gıda enzimi olmuştur; bugün peynirlerin büyük kısmı mikrobiyal kaynaklı kimozinle yapılır.'),
  ('Tek bir B lenfositi klonundan türeyen ve yalnızca tek bir antijenik bölgeyi tanıyan özdeş antikorlara ne ad verilir?', 'Monoklonal antikor', ['Poliklonal antiserum karışımı', 'Antijen', 'İnterferon'], 'Monoklonal antikorlar aynı dizili tek tip antikorlardır; poliklonal antiserum ise farklı bölgeleri tanıyan antikorların karışımıdır.'),
  ('Monoklonal antikor üretiminde kullanılan hibridoma hücreleri hangi iki hücrenin kaynaştırılmasıyla elde edilir?', 'Antikor üreten B lenfositi ile sınırsız bölünen miyeloma hücresi', ['Alyuvar ile trombosit', 'T lenfositi ile sinir hücresi', 'Bakteri hücresi ile antikor geni taşıyan maya hücresi'], 'B lenfositi antikor özgüllüğünü, miyeloma hücresi ise kültürde sınırsız çoğalma yeteneğini kazandırır.'),
  ('Burun örneğiyle yapılan ve 15–20 dakikada sonuç veren hızlı viral antijen testlerinde (lateral akış testleri) virüsü saptayan temel bileşen hangisidir?', 'Virüs proteinine özgü işaretli antikorlar', ['Virüs RNA\'sını çoğaltan polimeraz enzimi', 'Virüs DNA\'sını kesen restriksiyon enzimleri', 'Örnekteki virüs genlerini okuyan dizileme çipi'], 'Şeritteki antikorlar viral proteine bağlanır ve renkli çizgi oluşturur; nükleik asit çoğaltılmadığı için PCR\'dan daha az duyarlıdır ama çok daha hızlıdır.'),
  ('Bir antijenin ya da antikorun bir kuyucuğa bağlanıp, enzimle işaretlenmiş antikorun oluşturduğu renk değişimiyle ölçüldüğü laboratuvar testine ne ad verilir?', 'ELISA', ['PCR', 'Western blot', 'Ames testi'], 'ELISA (enzime bağlı immünosorbent test) virüs antikorlarının ve çeşitli hormonların taranmasında yaygın kullanılır.'),
  ('Tedavide kullanılan monoklonal antikorların adlarının çoğunlukla hangi ekle bittiği bilinir?', '-mab', ['-cilin', '-pril', '-olol'], 'Uluslararası adlandırmada monoklonal antikorlar "monoclonal antibody" kısaltmasından gelen -mab ekiyle biter (örneğin trastuzumab, rituksimab).'),
  ('Glifosat adlı yabani ot ilacına dayanıklı hâle getirilmiş transgenik soya ve mısır bitkilerinin çiftçiye sağladığı temel kolaylık nedir?', 'Tarla ilaçlandığında yabani otlar ölürken ürünün zarar görmemesi', ['Bitkinin hiç sulama gerektirmemesi', 'Bitkinin köklerinde kendi azotlu gübresini üretip toprağı zenginleştirmesi', 'Ürünün böceklere zehirli hâle gelmesi'], 'Bu bitkilere glifosatın etkilemediği bakteri kökenli bir enzim geni aktarılmıştır; ilaç yalnızca yabani otları öldürür.'),
  ('Denizanası ya da mercan kaynaklı floresan protein genleri aktarılarak ışıldayan renklerde üretilen ve evcil hayvan olarak satılan ilk genetiği değiştirilmiş hayvanlar hangileridir?', 'GloFish adlı süs balıkları', ['Dolly koyunları', 'Nakavt fareler', 'Transgenik süt keçileri'], 'Zebra balığına floresan protein geni aktarılarak elde edilen GloFish 2003\'te ABD\'de satışa sunuldu.'),
  ('Sütünde insan proteini üretecek biçimde genleri değiştirilmiş keçi ya da ineklerden ilaç elde edilmesine ne ad verilir?', 'Hayvan biyoreaktörü ("pharming")', ['Hibridoma', 'Yapay seçilim', 'Kriyoprezervasyon (dondurarak saklama)'], 'Süt bezine özgü bir promotörle bağlanan insan geni yalnızca sütte ifade edilir; örneğin antitrombin ilacı keçi sütünden üretilmiştir.'),
  ('Gen tedavisinde hastanın hücrelerinin vücuttan alınıp laboratuvarda genetik olarak değiştirildikten sonra geri verilmesine ne ad verilir?', 'Ex vivo gen tedavisi', ['In vivo gen tedavisi', 'Eşey hattı gen tedavisi', 'Kemoterapi'], 'Ex vivo yöntemde değiştirilen hücreler önce laboratuvarda denetlenir; in vivo yöntemde ise vektör doğrudan hastanın vücuduna verilir.'),
  ('Hastanın T lenfositlerine kanser hücresindeki bir antijeni tanıyan yapay bir reseptör geninin aktarılıp hücrelerin hastaya geri verildiği tedaviye ne ad verilir?', 'CAR-T hücre tedavisi', ['Kemik iliği nakli', 'Radyoterapi', 'Monoklonal antikor aşısı'], 'Kimerik antijen reseptörü (CAR) taşıyan T hücreleri kanser hücrelerini tanıyıp öldürür; bazı lösemi ve lenfomalarda kullanılır.'),
  ('Cas9\'un oluşturduğu çift zincir kırığı hücrede homolog olmayan uç birleştirmeyle onarılırsa genellikle ne olur?', 'Kırık yerinde küçük eklemeler ya da silmeler oluşur ve gen çoğu zaman işlevsiz kalır.', ['Gen her zaman kardeş kromatit kalıp alınarak tamamen doğru biçimde, hiç iz bırakmadan onarılır.', 'Kromozom tamamen kaybolur ve hücre bir sonraki bölünmede aneuploit hâle gelerek ölür.', 'Hücre bir sonraki bölünmede kromozomlarının yarısını kaybederek haploit hâle gelir.'], 'Hataya açık uç birleştirme çerçeve kayması mutasyonlarına yol açar; bu, bir geni "nakavt" etmenin en kolay yoludur.'),
  ('Tek yumurta ikizlerinin standart STR tabanlı DNA profiliyle birbirinden ayırt edilememesinin nedeni nedir?', 'Aynı zigottan geldikleri için STR profillerinin özdeş olması', ['Profillerinin yalnızca kan grubunda farklı olması', 'İkizlerde STR bölgesinin bulunmaması', 'İkizlerin DNA\'sının tek zincirli olması ve PCR ile çoğaltılamaması'], 'Tek yumurta ikizlerinin genomları neredeyse aynıdır; ayırt etmek için tüm genom dizilemesiyle çok nadir somatik mutasyonların aranması gerekir.'),
  ('Rekombinant DNA çalışmalarının olası riskleri üzerine bilim insanlarının 1975\'te Kaliforniya\'da toplanarak güvenlik kuralları önerdiği ünlü toplantı hangisidir?', 'Asilomar Konferansı', ['Solvay Konferansı', 'Rio Çevre ve Kalkınma Zirvesi', 'Helsinki Bildirgesi'], 'Paul Berg\'in de öncülerinden olduğu Asilomar Konferansı, deney türlerine göre fiziksel ve biyolojik önlem düzeyleri önerdi; bilimde öz denetimin simgesi oldu.'),
  ('Ekmek, yoğurt ve şarap yapımı gibi mikroorganizmalardan yararlanılan uygulamalar "geleneksel biyoteknoloji" olarak adlandırılır. "Modern biyoteknoloji"yi bunlardan ayıran temel özellik hangisidir?', 'Canlıların genetik maddesinin doğrudan ve hedefli olarak değiştirilebilmesi', ['Mikroorganizmaların hiç kullanılmaması', 'Yalnızca hayvan dokularının kullanılması ve bitkilerin, mikropların hiç işe karışmaması', 'Üretilen ürünlerin yalnızca yiyecek olması ve ilaç ya da enzim üretilmemesi'], 'Modern biyoteknoloji 1970\'lerden itibaren rekombinant DNA, hücre kültürü ve genom düzenleme gibi tekniklerle genleri doğrudan değiştirmeye dayanır.'),
  ('Bir biyoteknoloji tesisinde mikroorganizmaların sıcaklık, pH ve oksijen düzeyi denetlenen büyük kaplarda üretilerek bir ürünün elde edildiği düzeneğe ne ad verilir?', 'Biyoreaktör', ['Santrifüj', 'Spektrofotometre', 'Elektroforez tankı ve güç kaynağı'], 'Biyoreaktörlerde ilaçlar, enzimler ve organik asitler gibi ürünler büyük ölçekte üretilir.'),
  ('Modern biyoteknolojinin canlı genetiği değiştirilmiş organizmaların sınır ötesi taşınmasını düzenleyen ve 2000\'de kabul edilip 2003\'te yürürlüğe giren uluslararası protokol hangisidir?', 'Cartagena Biyogüvenlik Protokolü', ['Kyoto Protokolü', 'Montreal Protokolü', 'Ramsar Sözleşmesi'], 'Biyolojik Çeşitlilik Sözleşmesi\'ne bağlı Cartagena Protokolü, GDO ihracatında önceden bilgilendirilmiş onay ilkesini getirir. Kyoto iklim, Montreal ozon tabakası, Ramsar ise sulak alanlarla ilgilidir.'),
  ('Laboratuvarlarda çalışılan mikroorganizmaların tehlike düzeyine göre belirlenen biyogüvenlik düzeyleri (BSL-1\'den BSL-4\'e) için hangisi doğrudur?', 'Ebola gibi ölümcül etkenlerle en yüksek düzey olan BSL-4\'te çalışılır.', ['Bütün mikroorganizmalarla aynı güvenlik düzeyinde çalışılır.', 'BSL-1, en tehlikeli etkenler için ayrılmış düzeydir.', 'Biyogüvenlik düzeyleri yalnızca bitki laboratuvarları için geçerlidir; mikrobiyoloji laboratuvarlarında kullanılmaz.'], 'Düzey yükseldikçe koruyucu giysi, negatif basınçlı odalar ve atık arıtımı gibi önlemler artar; zararsız E. coli suşlarıyla BSL-1\'de çalışılabilir.'),
  ('Genetik bilgilerin işverenler ya da sigorta şirketleri tarafından ayrımcılık amacıyla kullanılması kaygısı hangi biyoetik konusuyla ilgilidir?', 'Genetik mahremiyet ve ayrımcılık', ['Biyolojik çeşitliliğin ve nesli tükenen türlerin korunması', 'Hayvan deneyleri', 'Organ bağışı ve nakil sıralaması'], 'Bu kaygı nedeniyle örneğin ABD\'de 2008\'de genetik bilgiye dayalı iş ve sağlık sigortası ayrımcılığını yasaklayan bir yasa (GINA) çıkarılmıştır.'),
  ('Çift zincirli DNA\'da şeker, fosfat ve baz sayıları arasındaki ilişki için hangisi doğrudur?', 'Deoksiriboz sayısı = fosfat sayısı = baz sayısı', ['Fosfat sayısı baz sayısının iki katıdır.', 'Deoksiriboz sayısı baz çifti sayısına eşittir.', 'Baz sayısı fosfat sayısının yarısıdır.'], 'Her nükleotit bir şeker, bir fosfat ve bir baz içerdiğinden bu üç sayı nükleotit sayısına eşittir.'),
  ('DNA elde etme deneyinin son basamağında özütün üzerine soğuk etil alkol dökülünce iki sıvının sınırında beyaz, iplik gibi bir yığın oluşur. Bunun nedeni hangisidir?', 'DNA\'nın alkolde çözünmeyip çökmesi', ['DNA\'nın alkolle tepkimeye girip proteine dönüşmesi', 'Alkolün DNA\'yı parçalayarak gaz çıkarması', 'Alkolün hücre duvarını yeniden oluşturması'], 'DNA suda çözünür ama alkolde çözünmez; alkol katmanında çöker ve uzun molekülleri birbirine dolanarak gözle görülen iplikler oluşturur.'),
  ('Laboratuvarda saf DNA elde ederken özüte proteaz enzimi eklenmesinin nedeni nedir?', 'DNA\'ya bağlı histonları ve diğer proteinleri parçalamak', ['DNA\'yı daha kısa parçalara kesmek', 'Lipitleri çözmek', 'Ortamdaki RNA\'yı DNA\'ya çevirmek'], 'Proteaz histonları ve DNaz gibi DNA\'yı yıkabilecek enzimleri sindirerek daha saf ve bozulmamış DNA elde edilmesini sağlar.'),
  ('Jel elektroforezinde örneklerin yanında bilinen boylardaki DNA parçalarından oluşan bir karışımın (DNA merdiveni) da yürütülmesinin amacı nedir?', 'Örnekteki parçaların boyunu karşılaştırarak tahmin edebilmek', ['Jelin elektriği iletmesini sağlamak', 'Örnekteki DNA\'yı çoğaltmak', 'DNA\'yı RNA\'ya dönüştürmek'], 'Merdivendeki bantların boyu bilindiği için aynı jeldeki bilinmeyen bantların boyu bunlarla kıyaslanarak bulunur.'),
  ('Elektroforezden sonra jeldeki DNA bantlarını görünür kılmak için kullanılan boyalar hangi özelliklerinden dolayı tercih edilir?', 'DNA\'ya bağlandıklarında ultraviyole ya da mavi ışık altında ışıma yapmaları', ['DNA\'yı yükseltgenerek kırmızıya boyamaları', 'DNA\'yı jelden çıkarıp kâğıda aktarmaları', 'DNA\'nın boyunu iki katına çıkarmaları'], 'Etidyum bromür ya da daha güvenli yeni boyalar DNA\'ya bağlanınca floresan verir; bantlar bu sayede görülür.'),
  ('Jele yüklemeden önce DNA örneklerine gliserol ve renkli boya içeren yükleme tamponu eklenir. Bu tampondaki gliserolün işlevi nedir?', 'Örneği ağırlaştırarak kuyucuğun dibine çökmesini sağlamak', ['DNA\'yı parçalamak', 'DNA\'yı floresan hâle getirmek', 'Akımın yönünü değiştirmek'], 'Gliserol örneğin yoğunluğunu artırır, böylece örnek tampon içinde yüzüp dağılmaz; renkli boya ise yürümenin izlenmesini sağlar.'),
  ('İnsanda fetüsün kanında yetişkinlerden farklı olarak γ (gama) globin zinciri içeren hemoglobin bulunur ve doğumdan sonra bu zincirin yerini giderek β zinciri alır. Bu değişim neyin örneğidir?', 'Gelişim sırasında gen ifadesinin düzenlenmesi', ['Mutasyonla yeni bir alel oluşması', 'Hemoglobin genlerinin kromozomdan silinmesi', 'Alyuvarların çekirdek kazanması'], 'Hem γ hem β genleri bütün yaşam boyunca DNA\'da bulunur; değişen, hangisinin ifade edildiğidir.'),
  ('Proto-onkogen kavramı en doğru nasıl tanımlanır?', 'Normal hücre büyümesi ve bölünmesinde görev alan, değiştiğinde onkogene dönüşebilen gen', ['Yalnızca kanser hücrelerinde bulunan virüs geni', 'Hücre bölünmesini her zaman durduran gen', 'Mitokondride bulunan ve kanseri önleyen gen'], 'Proto-onkogenler büyüme faktörleri, reseptörler ve sinyal proteinleri gibi normal ürünler kodlar; nokta mutasyonu, gen amplifikasyonu ya da translokasyonla aşırı etkin hâle gelebilirler.'),
  ('Bir bitkinin küçük bir doku parçasının steril besiyerinde hormonlarla yönlendirilerek kısa sürede binlerce genetik olarak özdeş fide üretilmesine ne ad verilir?', 'Mikroçoğaltım', ['Çapraz tozlaşma', 'Aşılama', 'Tohum ıslahı'], 'Bitki hücrelerinin totipotent olması sayesinde tek bir doku parçasından tam bitkiler yetiştirilebilir; muz ve orkide üretiminde yaygındır.'),
  ('Mikroçoğaltımla üretilen fidelerin tamamının genetik olarak ana bitkiyle aynı olması, bir meyve bahçesi için hangi riski doğurur?', 'Yeni bir hastalığa karşı bütün bitkilerin aynı ölçüde savunmasız kalması', ['Fidelerin tohum oluştururken kromozom sayılarının yarıya inmesi ve kısırlaşması', 'Bitkilerin fotosentez yapamaması', 'Fidelerin her birinin farklı meyve vermesi'], 'Klonlarda genetik çeşitlilik bulunmadığından bir patojen bir bitkiyi etkileyebiliyorsa hepsini etkileyebilir; 19. yüzyıl İrlanda patates kıtlığı bu tehlikeye bir örnektir.'),
  ('2010\'da J. Craig Venter Enstitüsü\'nün bilgisayarda tasarlanıp kimyasal olarak sentezlenen bir bakteri genomunu başka bir bakteri hücresine aktararak "yaşayan" bir hücre elde etmesi hangi alanın önemli bir aşaması sayılır?', 'Sentetik biyoloji', ['Paleontoloji', 'Biyocoğrafya', 'Ekoloji'], 'Mycoplasma mycoides genomu sentezlenip çekirdeği alınmış gibi davranan bir hücreye yerleştirildi; hücre yeni genomun yönetiminde çoğaldı.'),
  ('Viral vektör aşılarında (örneğin çoğalamayan adenovirüs kullanılan aşılarda) koruyucu bağışıklık nasıl oluşturulur?', 'Vektör patojen proteininin genini taşır; hücre proteini üretir ve bağışıklık gelişir.', ['Vektör patojenin canlı ve hastalık yapabilen tam hâlini vücuda verir.', 'Vektör yalnızca hazır antikor içerir; bu antikorlar birkaç hafta içinde yıkılır ve kalıcı bellek bırakmaz.', 'Vektör vücuttaki bütün bakterileri öldürür.'], 'Zararsız hâle getirilmiş virüs bir taşıyıcı olarak kullanılır; patojenin kendisi verilmediği için hastalık oluşmaz.'),
  ('Bir bakteriyofajın konak bakteriye girdikten sonra hemen çoğalıp bakteriyi parçalayarak yeni fajları serbest bırakmasına ne ad verilir?', 'Litik döngü', ['Lizojenik (ılıman) döngü', 'Konjugasyon', 'Transpozisyon'], 'Litik döngüde faj konağın sentez düzeneğini kullanarak kendini çoğaltır ve hücreyi patlatarak çıkar.'),
  ('Lambda fajının DNA\'sının bakteri kromozomuna yerleşip bakteriyle birlikte kuşaklar boyunca kopyalandığı evrede bu faj DNA\'sına ne ad verilir?', 'Profaj', ['Plazmit', 'Kapsit', 'Provirüs'], 'Lizojenik döngüde kromozoma yerleşmiş faj DNA\'sı profaj olarak adlandırılır; uygun koşullarda kromozomdan ayrılıp litik döngüye geçebilir.'),
  ('Retrovirüslerin yaşam döngüsünde, ters transkriptazla oluşturulan viral DNA\'yı konak hücrenin kromozomuna yerleştiren enzim hangisidir?', 'İntegraz', ['Helikaz', 'Primaz', 'DNA ligaz'], 'İntegraz viral DNA\'yı kromozoma ekler; yerleşen bu DNA\'ya provirüs denir. İntegraz baskılayıcıları HIV tedavisinde kullanılır.'),
  ('Prokaryotlarda tek bir mRNA molekülünün birden fazla proteini kodlayabilmesine ne ad verilir?', 'Polisistronik mRNA', ['Monosistronik mRNA', 'Olgun mRNA', 'Kırpılmış mRNA'], 'Operonlardan kopyalanan mRNA\'lar birden çok kodlama bölgesi içerir ve her birinin kendi ribozom bağlanma yeri bulunur. Ökaryot mRNA\'ları ise genellikle tek protein kodlar.'),
  ('Bir hücre kültüründe DNA sentezi yapan hücreleri işaretlemek için radyoaktif ya da kimyasal olarak etiketlenmiş timidin kullanılmasının nedeni nedir?', 'Timidinin yalnızca DNA\'ya katılması', ['Timidinin yalnızca proteinlere katılması', 'Timidinin hücre zarında birikmesi', 'Timidinin RNA\'ya katılıp DNA\'ya hiç katılmaması'], 'Timin RNA\'da bulunmadığı için işaretli timidin yalnızca eşlenme yapan, yani S evresindeki hücrelerin DNA\'sında görülür.'),
  ('Enzimlerin genlerinde rastgele mutasyonlar oluşturup istenen özelliği en iyi gösteren varyantları art arda seçerek yeni enzimler geliştirme yöntemiyle 2018 Nobel Kimya Ödülü\'nün yarısını alan bilim insanı kimdir?', 'Frances Arnold', ['Jennifer Doudna', 'Ada Yonath', 'Dorothy Hodgkin'], 'Arnold\'un yönlendirilmiş evrim yöntemi, doğal seçilimin laboratuvarda hızlandırılmış bir taklidi olarak biyoyakıt ve ilaç üretiminde kullanılan enzimler geliştirmeyi sağladı.'),
  ('Türleri tanımlamak için hayvanlarda mitokondriyal sitokrom c oksidaz I (COI) geninin kısa bir bölümünün dizilenmesine dayanan yönteme ne ad verilir?', 'DNA barkodlama', ['DNA parmak izi', 'Karyotipleme', 'Gen tedavisi ve klonlama'], 'Bu kısa dizi türler arasında yeterince farklı, tür içinde ise benzerdir; böylece bir doku parçasından türü belirlemek mümkün olur.'),
  ('Bakterilerin plastik atıkları parçalayan enzimlerini (örneğin PET plastiğini yıkan PETaz) mühendislikle iyileştirme çalışmalarının amacı hangisidir?', 'Plastiği yapı taşlarına ayırıp geri dönüşümü kolaylaştırmak', ['Plastiğin daha dayanıklı hâle gelmesini sağlamak', 'Bakterilerin plastik üretmesini engellemek', 'Plastik atıkları bakterilerin ürettiği ısıyla yüksek sıcaklıkta yakmak'], '2016\'da Japonya\'da bir geri dönüşüm tesisinde PET\'i besin olarak kullanabilen Ideonella sakaiensis bakterisi bulundu; enzimleri daha hızlı çalışacak biçimde geliştirilmektedir.'),
  ('Genetik kodda glisin GGU, GGC, GGA ve GGG kodonlarıyla kodlanır. Bir glisin kodonunun üçüncü bazında oluşan herhangi bir nokta mutasyonu için hangisi doğrudur?', 'Amino asit değişmez; mutasyon sessizdir.', ['Her zaman dur kodonu oluşur.', 'Her zaman okuma çerçevesi kayar.', 'Glisin her zaman alanine dönüşür ve proteinin yapısı bozulur.'], 'Üçüncü konum hangi bazla değişirse değişsin kodon GGN olarak kalır ve yine glisini kodlar.'),
  ('Ökaryotlarda gen ifadesinin hangi aşamalarda düzenlenebileceğine ilişkin en doğru ifade hangisidir?', 'Kromatin yapısından protein yıkımına kadar birçok aşamada düzenlenebilir.', ['Yalnızca DNA eşlenmesi sırasında düzenlenebilir.', 'Yalnızca translasyondan sonra, protein yıkım hızı değiştirilerek düzenlenebilir.', 'Ökaryotlarda gen ifadesi hiç düzenlenmez.'], 'Kromatin açılması, transkripsiyon, RNA işlenmesi, çekirdekten çıkış, mRNA ömrü, translasyon ve protein yıkımı basamaklarının hepsi denetim noktası olabilir.'),
  ('mRNA aşılarında mRNA\'nın lipit nanoparçacıklar içine yerleştirilmesinin temel amacı nedir?', 'mRNA\'yı yıkımdan korumak ve hücreye girişini sağlamak', ['mRNA\'yı DNA\'ya dönüştürmek', 'Aşının tadını iyileştirmek', 'mRNA\'nın bağışıklık sistemine hiç görünmemesini sağlamak'], 'Çıplak mRNA dokudaki RNazlarca hızla yıkılır ve negatif yükü nedeniyle zardan geçemez; lipit kılıf hem korur hem de zarla kaynaşarak taşır.'),
  ('Kök hücrelerin laboratuvarda üç boyutlu ortamda kendiliğinden düzenlenerek bir organın küçük ve basitleştirilmiş benzerini oluşturmasıyla elde edilen yapılara ne ad verilir?', 'Organoit', ['Organel', 'Nükleoid', 'Kallus dokusu'], 'Beyin, bağırsak ya da böbrek organoitleri hastalıkların ve ilaç etkilerinin insan dokusunda incelenmesini sağlar.'),
  ('İnsan genomundaki bir genin "alelleri" moleküler düzeyde en doğru nasıl tanımlanır?', 'Aynı gen bölgesinin bireyler arasında dizi bakımından farklılık gösteren biçimleri', ['Aynı kromozomdaki farklı genler', 'Bir genin ürettiği farklı protein türleri', 'Bir genin mRNA ve protein hâlleri'], 'Aleller aynı lokusun farklı dizi varyantlarıdır; bu farklar bir baz kadar küçük ya da bir bölgenin silinmesi kadar büyük olabilir.'),
  ('CRISPR-Cas9 uygulamalarında "hedef dışı etki" kavramıyla anlatılmak istenen nedir?', 'Kılavuz RNA\'ya benzeyen başka genom bölgelerinin de istenmeden kesilmesi', ['Cas9\'un hiç kesim yapmaması', 'Kılavuz RNA\'nın proteine çevrilmesi', 'Düzenlenen genin mitokondriye taşınıp orada ifade edilmesi'], 'Kılavuz RNA birkaç baz uyuşmazlığına rağmen benzer dizilere bağlanabilir; bu kesimler istenmeyen mutasyonlara yol açabilir. Daha özgül Cas9 türevleri bu riski azaltmak için geliştirilmiştir.'),
  ('Tek zincirli RNA moleküllerinin çoğu zaman düz bir iplik gibi değil, karmaşık üç boyutlu biçimlerde bulunmasının nedeni nedir?', 'Zincirin kendi üzerine katlanıp tamamlayıcı bölgeleri arasında baz eşleşmesi yapabilmesi', ['RNA\'nın histonlara sarılması', 'RNA\'nın timin içermesi', 'RNA\'nın yalnızca çekirdekte bulunması ve çekirdek zarına tutunarak biçim alması'], 'Saç tokası, ilmek ve sap gibi ikincil yapılar RNA\'ya özgül biçimler kazandırır; tRNA, rRNA ve ribozimlerin işlevi bu yapılara bağlıdır.'),
  ('Bakterilerde bir genin transkripsiyonu bitmeden ribozomların mRNA\'yı çevirmeye başlaması (eş zamanlı transkripsiyon-translasyon) bakteriye hangi avantajı sağlar?', 'Çevresel değişikliğe çok hızlı protein üretimiyle yanıt verebilme', ['Proteinlerin daha uzun ömürlü olması', 'mRNA\'nın kırpılabilmesi', 'Genlerin intron kazanması ve alternatif kırpılmayla çeşitlenmesi'], 'Gen açıldıktan kısa süre sonra protein sentezlenmeye başlar; bu hız, değişken ortamlarda yaşayan bakteriler için önemlidir.'),
  ('Transgenik bitki hücreleri seçilirken aktarılan gene ek olarak kanamisin gibi bir antibiyotiğe direnç geni de eklenmesinin amacı nedir?', 'Yabancı DNA\'yı almış hücrelerin antibiyotikli ortamda seçilebilmesi', ['Bitkiyi bakteriyel hastalıklara karşı kalıcı olarak korumak', 'Antibiyotiği bitkide üretip ilaç olarak satmak', 'Bitkinin daha hızlı fotosentez yapmasını ve daha erken çiçeklenmesini sağlamak'], 'Gen aktarımı az sayıda hücrede başarılı olur; seçici işaret, başarılı hücrelerin binlerce başarısız hücre arasından ayıklanmasını sağlar.'),
  ('Geri kalan zincirdeki kısa DNA parçalarının varlığını 1968\'de gösteren ve parçalara adını veren bilim insanı kimdir?', 'Reiji Okazaki', ['Arthur Kornberg', 'Matthew Meselson', 'Hamilton Smith'], 'Japon moleküler biyolog Reiji Okazaki ve eşi Tsuneko Okazaki, eşlenmenin bir zincirde kesikli gerçekleştiğini deneysel olarak gösterdi.'),
  ('Bir hücrede belirli bir anda üretilen bütün RNA moleküllerinin topluca dizilenerek hangi genlerin ne düzeyde ifade edildiğinin ölçülmesine ne ad verilir?', 'RNA dizilemesi', ['Genom dizilemesi', 'Karyotipleme ve FISH analizi', 'Proteom analizi'], 'Transkriptom hücrenin RNA\'larının tümüdür; RNA dizilemesi mikrodizilerden farklı olarak önceden bilinen problara bağlı kalmadan yeni transkriptleri de saptayabilir.'),
  ('Bir mRNA\'da başlama kodonu dışında, kodlama bölgesinin ortasında ve okuma çerçevesi içinde bulunan AUG kodonu için hangisi doğrudur?', 'Proteine bir metiyonin eklenmesini sağlar.', ['Translasyonu durdurur.', 'Yeni bir ribozomun bağlanmasını zorunlu kılar.', 'Okunmadan atlanır.'], 'AUG hem başlama kodonu hem de metiyonin kodonudur; okuma çerçevesi içinde ortaya çıktığında polipeptide metiyonin eklenir.'),
  ('Bakterilerin CRISPR bölgesinde art arda dizilmiş kısa tekrarların arasında yer alan "aralayıcı" dizilerin kaynağı nedir?', 'Daha önce karşılaşılan faj ya da plazmitlerin DNA parçaları', ['Bakterinin kendi ribozom genleri', 'İnsan genomundan alınmış diziler', 'Rastgele sentezlenmiş ve hiçbir kaynağa benzemeyen diziler'], 'Bakteri hayatta kaldığı enfeksiyonlardan küçük parçaları bu bölgeye ekler; bu parçalar daha sonra kılavuz RNA olarak kullanılarak aynı fajın yeniden tanınmasını sağlar.'),
  ('Bir öğrenci "Bir organizmanın bütün hücrelerinde aynı genler bulunduğuna göre bütün hücreler aynı proteinleri üretir" diyor. Bu ifadeyi çürüten en uygun örnek hangisidir?', 'Hemoglobinin alyuvar öncüllerinde, insülinin beta hücrelerinde üretilmesi', ['Bütün hücrelerin ribozom içermesi', 'Bütün hücrelerin hücre zarına sahip olması', 'Vücuttaki bütün hücrelerde glikoliz enzimlerinin bulunması ve sürekli ifade edilmesi'], 'Genlerin varlığı ifade edilmeleri anlamına gelmez; hücre tipine özgü proteinler farklı gen ifadesi programlarının sonucudur.'),
  ('Bir genin transkripsiyon başlangıç noktası ile çeviri başlangıç noktası (AUG) için hangisi doğrudur?', 'Genellikle aynı yerde değildir; arada 5\' çevrilmeyen bölge bulunur.', ['Her zaman tam olarak aynı nükleotittir.', 'Transkripsiyon her zaman AUG\'nin 3\' tarafından başlar.', 'Translasyon, RNA polimerazın bağlandığı promotör dizisinin içinden başlar.'], 'mRNA\'nın 5\' ucu ile başlama kodonu arasında, ribozomun bağlanmasına yardım eden 5\' UTR yer alır.'),
  ('Bir DNA çift sarmalının bir zincirinde 5\'-AGCTTC-3\' dizisi bulunuyor. Aynı bölgenin tamamlayıcı zinciri 3\'→5\' yönünde okunduğunda hangi dizi elde edilir?', '3\'-TCGAAG-5\'', ['3\'-GAAGCT-5\'', '3\'-AGCTTC-5\'', '3\'-UCGAAG-5\''], 'Tamamlayıcı zincir karşılıklı olarak yazılır: A-T, G-C, C-G, T-A, T-A, C-G; yani 3\'-TCGAAG-5\'. Urasil DNA\'da bulunmaz.'),
  ('Bir öğrenci aynı DNA örneğini EcoRI ile kestikten sonra jele yüklüyor, ancak enzim eklemeyi unuttuğu bir kontrol tüpünü de yan kuyucuğa koyuyor. Kontrol kuyucuğunda ne görmesi beklenir?', 'Kesilmemiş büyük DNA\'ya ait tek ya da az sayıda bant', ['Enzimli tüple aynı bant deseni', 'Hiç DNA bulunmadığı için tamamen boş bir kuyucuk ve iz bırakmayan şerit', 'Çok sayıda küçük parça'], 'Enzim olmadan DNA kesilmez; bu kontrol, enzimli tüpteki bantların gerçekten kesim sonucu oluştuğunu gösterir.'),
];
